/* The forward pulse is a root of a Nyquist pulse: its baseband form (from
 * hst_fpulse, the carrier taken off) against itself at whole symbols, at
 * most -40 dB from the centre (the spectrum test, pulse_points, sees the
 * magnitude only). Then through the transmitter and the receiver as they
 * are when it starts (noiseless, no line; the guard, the matched filter,
 * the timing from AB; nothing adapted): 400 points of the 4-point training
 * (S3, or V.17's conditioning), turned and scaled by the best complex gain,
 * at least 25 dB above their scatter about A..D. */
#define ZN 400
static void zero_isi(void)
{
    static hst_frx_t r2;
    static double g[10 * HST_FL], zr[ZN], zi[ZN];
    static int dx[ZN], dy[ZN];
    static hst_ftx_t t;
    double r0 = 0, worst = 0, ar = 0, ai = 0, ph, pz = 0, sc, cr = 0, ci = 0, num = 0, den = 0, snr;
    src_t s = { 0x15151u, 0 };
    int n, m, k, st, px, py, started = 0, nz = 0;
    for (n = 0; n < 10 * HST_FL; n++) {
        double w = 2 * PI * 1800.0 * n / 3.0 / FS;
        g[n] = hst_fpulse[n % 10][n / 10][0] * cos(w) + hst_fpulse[n % 10][n / 10][1] * sin(w);
    }
    for (n = 0; n < 10 * HST_FL; n++) r0 += g[n] * g[n];
    for (m = 1; m < HST_FL; m++) {
        double a = 0;
        for (n = 0; n + 10 * m < 10 * HST_FL; n++) a += g[n] * g[n + 10 * m];
        if (fabs(a) / r0 > worst) worst = fabs(a) / r0;
    }
    printf("zero_isi: the pulse against itself at 1 .. %d symbols\n", HST_FL - 1);
    if (verbose) printf("  (at most %.1f dB from the centre)\n", 20 * log10(worst + 1e-30));
    bound("the pulse's own ISI at most -40 dB", 20 * log10(worst + 1e-30) <= -40);

    hst_ftx_init(&t, FLEVEL, src_bit, &s);
    hst_frx_init(&R);
    hst_ftx_train(&t, 6, 1);
    for (n = 0; n < 3 * FS && nz < ZN; n++) {
        int16_t x = hst_ftx_tick(&t);
        (void)hst_frx_tick(&R, x);
        if (!started) {
            if (hst_frx_state(&R) == HST_FRX_TRAIN) { r2 = R; started = 1; }
            continue;
        }
        if (qamrx_tick(&r2.q, hst_gf_tick(&r2.gf, x))) {
            qamrx_update(&r2.q, 0, 0, 0, 14);            /* nothing adapted */
            if (r2.q.nsym > 150) { zr[nz] = r2.q.zr; zi[nz] = r2.q.zi; nz++; }   /* in S3 */
        }
    }
    /* the turn, modulo a quarter, from the points' fourth power (A is
     * (-6, -2)); each point's nearest of A..D; the least-squares gain */
    for (k = 0; k < nz; k++) {
        double a2 = zr[k] * zr[k] - zi[k] * zi[k], b2 = 2 * zr[k] * zi[k];
        ar += a2 * a2 - b2 * b2; ai += 2 * a2 * b2;
        pz += zr[k] * zr[k] + zi[k] * zi[k];
    }
    ph = (atan2(ai, ar) - 4 * atan2(-2.0, -6.0)) / 4;
    sc = sqrt(40.0 * nz / (pz + 1e-30));
    for (k = 0; k < nz; k++) {
        double x = sc * (zr[k] * cos(ph) + zi[k] * sin(ph)), y = sc * (zi[k] * cos(ph) - zr[k] * sin(ph)), bd = 1e30;
        for (st = 0; st < 4; st++) {
            v32_state_point(st, &px, &py);
            if ((x - px) * (x - px) + (y - py) * (y - py) < bd) { bd = (x - px) * (x - px) + (y - py) * (y - py); dx[k] = px; dy[k] = py; }
        }
        cr += dx[k] * zr[k] + dy[k] * zi[k];
        ci += dy[k] * zr[k] - dx[k] * zi[k];
    }
    cr /= pz + 1e-30; ci /= pz + 1e-30;
    for (k = 0; k < nz; k++) {
        double er = cr * zr[k] - ci * zi[k] - dx[k], ei = cr * zi[k] + ci * zr[k] - dy[k];
        num += dx[k] * dx[k] + dy[k] * dy[k];
        den += er * er + ei * ei;
    }
    snr = 10 * log10(num / (den + 1e-30) + 1e-30);
    printf("zero_isi: transmitter to receiver, %d points of the 4-point training through the matched filter\n", nz);
    if (verbose) printf("  (%.1f dB above their scatter; their RMS %.2f of the 4 points)\n", snr, sqrt(pz / nz / 40) / HST_FRX_U);
    bound("through the receiver's start, nothing adapted: at least 25 dB", nz == ZN && snr >= 25);
}

int main(int argc, char **argv)
{
    int only;
#ifdef HST_PROFILE_BM
    only = t_case_arg(argc, argv, 7);
#else
    if (argc == 2 && strcmp(argv[1], "thresholds") == 0) {
#ifdef TEST_FULL
        thresholds();
        return 0;
#else
        printf("thresholds: build with -DTEST_FULL (make hst-thresh)\n");
        return 2;
#endif
    }
    only = t_case_arg(argc, argv, 23);
#endif
    verbose = getenv("HST_VERBOSE") != NULL;
    if (T_CASE(only, 1)) pulse_points();
    if (T_CASE(only, 2)) guard();
    if (T_CASE(only, 3)) v32_default();
#ifdef HST_PROFILE_BM
    if (T_CASE(only, 4)) bm();
    if (T_CASE(only, 5)) bm_short();
    if (T_CASE(only, 6)) acq_v17();
    if (T_CASE(only, 7)) zero_isi();
#else
    if (T_CASE(only, 4)) train_long();
    if (T_CASE(only, 5)) train_short();
    if (T_CASE(only, 6)) s1_s2();
    if (T_CASE(only, 7)) trn();
    if (T_CASE(only, 8)) acq_long();
    if (T_CASE(only, 9)) acq_short();
    if (T_CASE(only, 10)) acq_offset();
    if (T_CASE(only, 11)) stored_eq();
    if (T_CASE(only, 12)) trn_as_ones();
    if (T_CASE(only, 13)) zero_isi();
    if (T_CASE(only, 14)) carrier_loss();
    if (T_CASE(only, 15)) carrier_return();
    if (T_CASE(only, 16)) dropout();
    if (T_CASE(only, 17)) train_fail();
    if (T_CASE(only, 18)) level_step();
    if (T_CASE(only, 19)) lock_loss();
    if (T_CASE(only, 20)) carrier_stop_noisy();
    if (T_CASE(only, 21)) harsh_dropout();
    if (T_CASE(only, 22)) marks_switch();
    if (T_CASE(only, 23)) marks_missed();
#endif
    T_REPORT("test_hst_fwd");
}
